(function ($) {
	$(document).ready(function () {
		fixSizes();
		$('a[data-fancybox], .video a').fancybox({
			smallBtn : true,
			helpers:  {
				title : {
					type : 'inside'
				},
				media: true
			},
			caption : function( instance, item ) {
				var caption = $(this).attr('title') || '';
				var description = $(this).attr('data-description') || ''

				caption = (caption.length ? caption + '<br />' + description : '');
				return caption;
			},
			youtube: {
				autoplay: 1
			}
		});
		$('.faq').accordion({
			collapsible: true,
			active: false,
			heightStyle: 'content'
		});
		$('.wpcf7-submit').click(function (e) {
			var form = $(this).closest('form');
			var tel = form.find('[name="tel"]');
			var email = form.find('[name="email"]');
			if(tel.length && email.length){
				if(emailValidation(email.val()) || phoneValidation(tel.val())){
					form.find('.wpcf7-response-output').hide();
					form.find('.wpcf7-response-output').html('');
				}else{
					e.preventDefault()
					form.find('.wpcf7-response-output').addClass('wpcf7-validation-errors').html("We'd love to get back to you. Please fill in either email or phone fields.");
					form.find('.wpcf7-response-output').show();
				}
			}
		});
	});

	$(window).resize(function () {
		fixSizes();
	});

	function fixSizes() {

	};
	// $( function() {
	// 	$( ".testimonials-holder" ).sortable();
	// } );
	
})(jQuery)

function emailValidation(data) {
	if (/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/.test(data)) {
		return true
	}
	return false
}

function phoneValidation(data) {
	if(!data){
		return false;
	}
	var length = data.match(/\d/g).length
	return length==9 || length == 10;
}
